{
  "title": "HCV Treatment Adherence Game",
  "perWatchSecond": 5,
  "levels": [
    {
      "kind": "hook",
      "finding": 0,
      "title": "Adherence Threshold",
      "goal": "Discover the adherence level that stops HCV spread.",
      "control": {
        "parameter": "theta",
        "label": "Treatment Adherence Proportion",
        "lowEnd": "0.0 (no adherence)",
        "highEnd": "1.0 (full adherence)"
      },
      "watch": "cq",
      "whatIf": {
        "prompt": "What if adherence is increased to 60%?",
        "parameter": "theta",
        "value": 0.6
      },
      "difference": {
        "compartment": "cq",
        "summary": "peak",
        "at": null,
        "time": 200,
        "relation": "lower",
        "by": 0.004
      },
      "effect": "With 60% adherence, the peak number of chronically infected who quit treatment drops below the level seen at 50% adherence.",
      "prediction": {
        "prompt": "Will higher adherence reduce the peak of quit patients?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Headline Result",
        "quote": "an adherence level exceeding 52% causes the reproduction number to drop below 1, curtailing further spread."
      },
      "carryForward": "Keep theta at 0.6 for next levels."
    },
    {
      "kind": "idea",
      "finding": 3,
      "title": "Combined Recovery Boost",
      "goal": "See how faster acute recovery and higher adherence together affect transmission.",
      "control": {
        "parameter": "r2",
        "label": "Acute Recovery Rate",
        "lowEnd": "0.05 (slow)",
        "highEnd": "0.25 (fast)"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if acute recovery rate is doubled to 0.326?",
        "parameter": "r2",
        "value": 0.326
      },
      "difference": {
        "compartment": "i",
        "summary": "peak",
        "at": null,
        "time": 200,
        "relation": "lower",
        "by": 0.005
      },
      "effect": "Doubling the acute recovery rate, with 60% adherence, lowers the peak of acutely infected individuals.",
      "prediction": {
        "prompt": "Will faster acute recovery reduce the infection peak?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": null,
      "carryForward": "Maintain theta = 0.6, r2 = 0.326."
    },
    {
      "kind": "result",
      "finding": 4,
      "title": "Quitters' Risk",
      "goal": "Compare transmission risk from quitters versus other groups.",
      "control": {
        "parameter": "beta3",
        "label": "Transmission Rate from Quitters",
        "lowEnd": "0.02 (low)",
        "highEnd": "0.08 (high)"
      },
      "watch": "r",
      "whatIf": {
        "prompt": "What if quitters' transmission rate is halved to 0.025?",
        "parameter": "beta3",
        "value": 0.025
      },
      "difference": {
        "compartment": "r",
        "summary": "peak",
        "at": null,
        "time": 200,
        "relation": "lower",
        "by": 0.003
      },
      "effect": "Halving the transmission rate from those who quit treatment reduces the peak number of recovered individuals.",
      "prediction": {
        "prompt": "Will reducing quitters' transmission lower the recovery peak?",
        "claimed": "lower",
        "other": "higher"
      },
      "passage": {
        "title": "Quitters' Impact",
        "quote": "$\\beta_{3}$ exerts the strongest influence on the reproduction number."
      },
      "carryForward": "Keep theta = 0.6, r2 = 0.326, beta3 = 0.025."
    }
  ],
  "limits": [
    "Each level runs for 200 time units (years) displayed at 4× speed within 20 seconds.",
    "Controls adjust only rate parameters (no starting values).",
    "What‑if changes a single parameter or initial condition discussed in the paper.",
    "Measured differences are clear on a chart (≥10% of chart height) and affect at least 3 of 120 figures."
  ]
}
